import{_ as e,c as r,o as t,K as s,ca as n}from"./chunks/framework.CqUzgkEo.js";const k=JSON.parse('{"title":"EaaS 사용자 피드백 제출","description":"피드백 채널이 사실상 없던 EaaS 제품에 Antigravity 의 Provide Feedback 을 참고해 가볍게 채널을 만든 과정과 그 안에서 내린 설계 결정을 정리해요.","frontmatter":{"title":"EaaS 사용자 피드백 제출","date":"2026-06-02T11:00+09:00","description":"피드백 채널이 사실상 없던 EaaS 제품에 Antigravity 의 Provide Feedback 을 참고해 가볍게 채널을 만든 과정과 그 안에서 내린 설계 결정을 정리해요.","tags":["eaas","product","feedback"]},"headers":[],"relativePath":"posts/eaas-user-feedback.md","filePath":"posts/eaas-user-feedback.md","lastUpdated":1782554754000}'),o={name:"posts/eaas-user-feedback.md"};function i(d,a,l,c,g,h){return t(),r("div",null,[...a[0]||(a[0]=[s('<h1 id="eaas-사용자-피드백-제출" tabindex="-1">EaaS 사용자 피드백 제출 <a class="header-anchor" href="#eaas-사용자-피드백-제출" aria-label="Permalink to “EaaS 사용자 피드백 제출”">​</a></h1><p><a href="/posts/google-agentic-update-terrible">최근 업데이트로 인해 사용자 경험에 문제가 많았던</a> Antigravity 에도 <strong>Provide Feedback</strong> 이라는 피드백 채널이 포함되어 있어요. 그런데 이와 비교해서 회사에서 만든 <code>EaaS(Energy as a Service)</code> 제품에는 사용자 의견을 받을 채널이 없더라구요. 비록 사용자 규모가 적더라도 의견을 전달할 수 있는 채널은 만들어두는 게 중요하지 않을까 생각해요.</p><h2 id="피드백-채널이-있어도-사용자는-이탈해요" tabindex="-1">피드백 채널이 있어도 사용자는 이탈해요 <a class="header-anchor" href="#피드백-채널이-있어도-사용자는-이탈해요" aria-label="Permalink to “피드백 채널이 있어도 사용자는 이탈해요”">​</a></h2><p><img src="'+n+'" alt="제품 푸터 — Copyright 와 그 아래의 사업자정보·문의하기 링크"></p><p>처음에는 <mark>피드백 채널이 없다</mark> 고 생각했는데 알고보니까 Copyright 영역에 <strong>사업자 정보</strong> 를 누르면 연락처가 포함되어있긴 하더라구요. 물론, 사용자 의견을 받기 위해서 넣어둔 건 아니었을거에요. 그나마 직관적인 <strong>문의하기</strong> 는 누르면 의도와 다른 브랜드 홈페이지로 이동해 버리더라구요.</p><p>그리고 피드백 채널이 명확히 있더라도 결국 <mark>사용자는 그냥 떠날 것</mark> 이라고 생각해요. 하지만, 사용자 이탈을 최소화할 장치가 마련되지 않았던 셈이죠. 백오피스 지표 중 <strong>고객 이탈률(Churn Rate)</strong> 은 서비스 품질 만족도를 직관적으로 보여주니까요.</p><p>사용자 입장에서 보면 피드백 채널을 찾는 것 자체가 어려워요. 그래서 그나마 서비스를 이용중이던 사용자에게도 <strong>&quot;의견을 전달할 방법이 없는 서비스&quot;</strong> 라는 인식이 굳어져 있었을 가능성이 커요.</p><h3 id="zendesk-같은-crm-도입을-하지-않는-이유" tabindex="-1">Zendesk 같은 CRM 도입을 하지 않는 이유 <a class="header-anchor" href="#zendesk-같은-crm-도입을-하지-않는-이유" aria-label="Permalink to “Zendesk 같은 CRM 도입을 하지 않는 이유”">​</a></h3><p>고객 의견을 수렴해야 할 때 보통 <a href="https://www.zendesk.kr/" target="_blank" rel="noreferrer">Zendesk</a> 같은 CRM SaaS 를 먼저 떠올리지만, 이번 EaaS 제품에는 과도하다고 보여요. 서비스 운영팀이 없을 뿐더러 <strong>자체 구현으로 가볍게 채널만 만들어두는게</strong> 더 적합해요.</p><p>Antigravity 의 Provide Feedback 은 Settings 화면에 있지만, 사용자에게는 간단한 선택지와 의견만 요구하고 있어요. 피드백 제출 기능 위치는 다소 깊어도 입력을 요구하는게 간단해서 의견을 남기는 행위에 부담이 없어요. 이와 비교해서, <a href="https://surveys.adguard.com/en/adguard_linux/form.html" target="_blank" rel="noreferrer">AdGuard 의 피드백 폼</a> 처럼 항목이 잘 정돈된 형식은 의견을 남기는 행위라기보다 <strong>설문조사에 참여하는 느낌</strong> 에 가까워서 의견을 제시하는 입장에선 약간 부담감이 듭니다.</p><h2 id="피드백-채널은-어디에-두어야-할까요" tabindex="-1">피드백 채널은 어디에 두어야 할까요? <a class="header-anchor" href="#피드백-채널은-어디에-두어야-할까요" aria-label="Permalink to “피드백 채널은 어디에 두어야 할까요?”">​</a></h2><p>피드백 채널을 어디에 두어야할 지 고민이 됐는데요. Antigravity 처럼 설정 메뉴 안에 넣으면 사용자가 &quot;여기에 피드백 채널이 있다&quot; 는 사실 자체를 인지하기 어렵지 않나 생각해요. 입력 폼이 아무리 간단해도, 채널이 있다는 걸 모르면 의미가 없지 않을까요?</p><p>회사 제품을 보니 사이드바 하단의 프로필 드롭다운이 <strong>설정 메뉴로 들어가는 진입점이자 로그아웃이 위치하는 자리</strong> 더라구요. 사이드바가 모든 화면에서 항상 노출되는 구조이면서 일반적으로 사용자가 자기 계정과 관련된 동작을 찾을 때 자연스럽게 거치는 곳이라, 피드백 채널을 여기에 같이 두는 게 그나마 인지하기 쉬운 위치라고 판단했어요.</p><h3 id="피드백-유형은-간단하게" tabindex="-1">피드백 유형은 간단하게 <a class="header-anchor" href="#피드백-유형은-간단하게" aria-label="Permalink to “피드백 유형은 간단하게”">​</a></h3><p>피드백 유형도 간단하게 몇가지 선택지만 주는게 좋아보여요. 선택지가 너무 많으면 사용자가 분류에 부담을 느끼고, 적으면 운영자가 의견을 받아서 다시 분류해야 해요. 고객 지원(CS) 관점에서 보았을때 4개 정도로 정의하면 될 것 같아요. 그리고, <mark>이미지 첨부는 Antigravity 에서 옵션으로 제공하지만 의도적으로 제외</mark>했어요. 정말로 간단한 피드백 채널을 만드는게 목표거든요.</p><ul><li><strong>Bug Report (버그)</strong> — 동작이 의도와 다른 경우</li><li><strong>Improvement (기능 개선)</strong> — 이미 있는 기능을 더 낫게 만드는 의견</li><li><strong>Feature Request (기능 제안)</strong> — 지금 없는 기능에 대한 요청</li><li><strong>Etc (기타 문의)</strong> — 나머지</li></ul><h2 id="접수된-피드백은-백오피스에서-관리" tabindex="-1">접수된 피드백은 백오피스에서 관리 <a class="header-anchor" href="#접수된-피드백은-백오피스에서-관리" aria-label="Permalink to “접수된 피드백은 백오피스에서 관리”">​</a></h2><p>회사에서 서비스 운영팀이 있는게 아니기 때문에 제출된 피드백을 확인할 수 있는 별도의 외부 채널을 만들지 않고 백오피스에 구현했어요. 슬랙 (또는 구글 워크스페이스 채팅) 같은 외부 메신저 채널을 붙이는 작업 자체가 별도 공수이기 때문이에요. 지금은 운영자가 백오피스에 관리자 계정으로 로그인해 피드백을 직접 확인하고, 처리 결과도 <strong>수동으로 이메일을 발송할 수 있는 버튼</strong> 으로 회신해요.</p><p>서비스가 성장해서 사용자 규모가 커지면 파이프라인 자동화가 필요해지긴 하겠죠. 그때는 Antigravity 의 Provide Feedback 하단에 제출하기 전에 있는 아래의 두가지 옵션은 흡수해도 좋을 것 같기도 해요.</p><h3 id="attach-antigravity-server-logs" tabindex="-1">Attach Antigravity server logs <a class="header-anchor" href="#attach-antigravity-server-logs" aria-label="Permalink to “Attach Antigravity server logs”">​</a></h3><p>OS·브라우저·콘솔 로그 같은 컨텍스트 정보를 자동으로 수집하면, 이미지 없이도 상황을 어느 정도 추적할 수 있어요.</p><h3 id="send-feedback-as-kdevkr-gmail-com" tabindex="-1">Send feedback as <a href="mailto:kdevkr@gmail.com" target="_blank" rel="noreferrer">kdevkr@gmail.com</a> <a class="header-anchor" href="#send-feedback-as-kdevkr-gmail-com" aria-label="Permalink to “Send feedback as kdevkr@gmail.com”">​</a></h3><p>지금은 백오피스에서 수동으로 회신하지만 처리되는 피드백이 많아지면 자동으로 통지되는 파이프라인이 나중에는 필요할 수 있어요.</p><h2 id="그래도-사용자는-이탈한다" tabindex="-1">그래도 사용자는 이탈한다. <a class="header-anchor" href="#그래도-사용자는-이탈한다" aria-label="Permalink to “그래도 사용자는 이탈한다.”">​</a></h2><p>솔직히 말하면, 피드백 채널을 명확히 제공하더라도 실제로 의견을 남기는 사용자는 많지 않아요. 서비스에 불편을 느낀 사용자도 의견을 남기기 전에 그냥 이탈해요. <mark>눈에 띄는 버튼이 있어도 대부분의 사용자는 아무 말 없이 떠나요.</mark> 제품 회의에서는 고객 피드백을 받아야 한다고 늘 이야기하지만, 막상 제가 사용자가 되어 다른 서비스를 쓸 때는 불편을 느끼더라도 피드백을 제출해 본 경험이 별로 없어요. 제품을 만드는 입장에서도, 사용자로서는 침묵하는 쪽이었던 거예요. 그래서 피드백 채널을 만드는 건 거창한 일이 아니지만 <mark>최소한의 사용자 의견을 들을 수 있는 창구를 남겨 두는 일</mark> 은 중요한거죠. 지금은 소중한 의견 한 건을 받는 게 우선이고, SLA 같은 지표를 따지는 건 나중 일이에요.</p><p>감사합니다.</p>',26)])])}const m=e(o,[["render",i]]);export{k as __pageData,m as default};
